if (!cssText.includes('brightness(') || !cssText.includes('saturate(')) return false;
if (!cssText.includes('--ai4a11y-filter-dim')) return false;

const rootStyle = window.getComputedStyle(document.documentElement);
const dimVar = rootStyle.getPropertyValue('--ai4a11y-filter-dim').trim();
if (!dimVar.includes('brightness') || !dimVar.includes('saturate')) return false;

const computedFilter = rootStyle.filter;
if (!computedFilter.includes('brightness') || !computedFilter.includes('saturate')) return false;

return true;

